using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using TMPro;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class PaperCardCheck {
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated required");g.SetBuild(BuildPreset.Manual);g.TryStartRun(42);g.SetPaused(true);var h=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();Action refresh=()=>typeof(BokumyakuBattleHud).GetMethod("Refresh",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(h,null);refresh();var cards=h.GetComponentsInChildren<Button>().Where(x=>Enumerable.Range(0,5).Any(i=>x.name=="Upgrade"+i)).OrderBy(x=>x.name).ToArray();if(cards.Length!=5||cards.Any(x=>x.interactable))throw new Exception("Zero ink state");foreach(var card in cards){var face=(Image)card.targetGraphic;if(face.sprite.name!="washi_card_07"||face.color!=Color.white||face.type!=Image.Type.Sliced||!face.fillCenter||card.transform.Find("BrushEdge")!=null)throw new Exception("Paper setup");}for(int i=0;i<1800;i++)g.Run.Tick();refresh();if(!cards[0].interactable)throw new Exception("Purchase unavailable");int before=g.Run.UpgradeLevels[0];cards[0].onClick.Invoke();refresh();if(g.Run.UpgradeLevels[0]!=before+1)throw new Exception("Purchase callback");Canvas.ForceUpdateCanvases();foreach(var t in h.GetComponentsInChildren<TextMeshProUGUI>()){t.ForceMeshUpdate();if(t.isTextOverflowing)throw new Exception("Overflow "+t.name);}var r=new{passed=true,width=Screen.width,height=Screen.height,cards=cards.Length,disabledAtZero=true,purchaseCallback=true,level=g.Run.UpgradeLevels[0],method="Isolated manual seed42; zero ink disabled then simulated 1800tick income and real button callback; visual inspection separate."};var path=Path.GetFullPath("../docs/evidence/paper-card-"+Screen.width);File.WriteAllText(path+".json",Newtonsoft.Json.JsonConvert.SerializeObject(r));ScreenCapture.CaptureScreenshot(path+".png");return r;}}
